CREATE TABLE relatorio(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, aluno_id bigint,owner_id bigint NOT NULL,professor_id bigint,released_only boolean NOT NULL,tipo varchar(255) NOT NULL,request_id varchar(255) NOT NULL,execution_id bigint,nome varchar(255),snapshot text,UNIQUE(owner_id,request_id));
CREATE TABLE linha(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,relatorio_id bigint NOT NULL REFERENCES relatorio(id),numero integer NOT NULL,conteudo text NOT NULL,UNIQUE(relatorio_id,numero));
